<?php
 namespace Pterodactyl\Services\Dezerx; use Illuminate\Support\Str; use Pterodactyl\Models\Egg; class EggRules { public const SETTING_KEY = 'egg_rules'; public const MAX = 100; public static function all(): array { $stored = Settings::get(self::SETTING_KEY) ?? []; $rules = []; foreach ((array) ($stored['rules'] ?? []) as $rule) { if (!is_array($rule) || !is_string($rule['id'] ?? null) || $rule['id'] === '') { continue; } $rules[] = [ 'id' => $rule['id'], 'eggs' => self::uuids($rule['eggs'] ?? []), 'allowed' => self::uuids($rule['allowed'] ?? []), ]; } return $rules; } public static function active(): bool { return self::all() !== []; } public static function allowedFor(?string $egg): array { if ($egg === null || $egg === '') { return []; } $allowed = []; foreach (self::all() as $rule) { if (in_array($egg, $rule['eggs'], true)) { array_push($allowed, ...$rule['allowed']); } } return array_values(array_unique($allowed)); } public static function sources(): array { $eggs = []; foreach (self::all() as $rule) { if ($rule['allowed'] !== []) { array_push($eggs, ...$rule['eggs']); } } return array_values(array_unique($eggs)); } public static function store(array $eggs, array $allowed): bool { $rules = self::all(); if (count($rules) >= self::MAX) { return false; } $rules[] = ['id' => Str::lower(Str::random(10))] + self::shape($eggs, $allowed); self::put($rules); return true; } public static function update(string $id, array $eggs, array $allowed): bool { $rules = self::all(); foreach ($rules as $index => $rule) { if ($rule['id'] === $id) { $rules[$index] = ['id' => $id] + self::shape($eggs, $allowed); self::put($rules); return true; } } return false; } public static function delete(string $id): void { self::put(array_filter(self::all(), fn (array $rule) => $rule['id'] !== $id)); } private static function shape(array $eggs, array $allowed): array { return [ 'eggs' => self::known($eggs), 'allowed' => self::known($allowed), ]; } private static function known(array $uuids): array { $uuids = self::uuids($uuids); return $uuids === [] ? [] : array_values(array_unique(array_map( 'strval', Egg::query()->whereIn('uuid', $uuids)->pluck('uuid')->all(), ))); } private static function uuids(mixed $value): array { return array_values(array_filter( array_map('strval', (array) $value), fn (string $uuid) => $uuid !== '', )); } private static function put(array $rules): void { Settings::put(self::SETTING_KEY, ['rules' => array_values($rules)]); } } 